"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[14993],{79089:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Dropdown","desc":"A reusable dropdown/select widget. Re-implemented from the GuiLib reference\\npattern \u2014 it does NOT require GuiLib. Drives a caller-authored button that has\\nan `Option` (TextLabel) and `Arrow` (ImageLabel) child, building a selectable\\noption list directly beneath it. Fully decoupled from any specific GUI, config,\\nor signal bus: callers connect `.Changed` and wire it themselves.\\n\\n```lua\\nlocal Dropdown = require(SharedModules.Gui.Dropdown)\\nlocal dropdown = Dropdown.new(button, {\\n\\t{ Value = \\"all\\", Label = \\"All\\" },\\n\\t{ Value = \\"weapons\\", Label = \\"Weapon\\" },\\n}, { StartValue = \\"all\\" })\\ndropdown.Changed:Connect(function(value)\\n\\tprint(\\"selected\\", value)\\nend)\\n```","realm":["Client"],"source":{"line":23,"path":"src/ReplicatedStorage/SharedModules/Gui/Dropdown.luau"}}')}}]);